<!-- src/components/Kitchen/Recipes/RecipeDetail.vue -->
<template>
    <v-container class="py-6">
        <div class="d-flex align-center mb-4">
        <div class="rowSpaceBetween fullWidth mb-5">
          <TopDeck
            firstElement="Détail"
            secondElement="recette"
            :coloredSecond="true"
            actionHeaderIcon="mdi-arrow-left"
            :actionheaderFunction="() => $router.back()"
            actionHeaderColor="accent"
            actionHeaderTextColor="white"
          />
          <div class="rowCustom">
            <ThemeToggle />
            <AccountToggle />
          </div>
        </div>
        </div>

        <v-card class="pa-4">
          <div class="d-flex align-center justify-space-between">
              <h2 class="text-h5 mb-2">{{ recipe?.title || 'Sans titre' }}</h2>
              <v-chip v-if="recipe?.category" color="primary" variant="tonal" size="small">
              {{ recipe.category }}
              </v-chip>
          </div>

          <div class="text-caption mb-3" v-if="recipe?.notes">
              {{ recipe.notes }}
          </div>

          <v-row>
              <v-col cols="12" md="6">
              <v-sheet class="pa-3 rounded-lg bg-tertiary">
                  <div class="text-subtitle-2 mb-1">Totaux recette</div>
                  <div class="text-body-2">
                    {{ recipe?.totals?.grams ?? 0 }} g — {{ recipe?.totals?.kcal ?? 0 }} kcal
                    <br>
                    Protéines {{ format1(recipe?.totals?.protein) }} g •
                    Glucides {{ format1(recipe?.totals?.carbs) }} g •
                    Lipides {{ format1(recipe?.totals?.fat) }} g
                  </div>
                  <div class="text-caption mt-2" v-if="recipe?.servings && recipe.servings > 0">
                    <strong>Par portion ({{ recipe.servings }}):</strong>
                    {{ Math.round((recipe?.totals?.kcal ?? 0) / recipe.servings) }} kcal
                  </div>
              </v-sheet>
              </v-col>
          </v-row>

          <v-divider class="my-4" />

          <div class="text-subtitle-1 mb-2">Ingrédients</div>
          <v-alert v-if="!recipe?.ingredients?.length" type="info" variant="tonal">
              Aucune ligne d’ingrédient.
          </v-alert>
          <v-list v-else density="comfortable" lines="two">
              <v-list-item v-for="(ing, i) in recipe.ingredients" :key="i">
                <v-list-item-title>
                    {{ ing.productName }}
                </v-list-item-title>
                <v-list-item-subtitle>
                    {{ ing.grams }} g
                </v-list-item-subtitle>
              </v-list-item>
          </v-list>
        </v-card>

        <!-- FAB actions vertical -->
        <v-fab-transition 
          v-if="!recipe?.baseRecipe || authStore.userInfos?.role === 'admin'"
        >
            <div class="fab-wrapper">
                <v-btn
                        color="accent"
                        class="fab"
                        icon
                        size="large"
                        elevation="6"
                        @click="fabOpen = !fabOpen"
                    >
                    <v-icon v-if="fabOpen" color="white">mdi-chevron-down</v-icon>
                    <v-icon v-else color="white">mdi-dots-vertical</v-icon>
                </v-btn>

                <div v-if="fabOpen" class="fab-actions-vertical">
                <!-- Modifier -->
        <v-btn
          v-if="!recipe?.baseRecipe || authStore.userInfos?.role === 'admin'"
          color="secondary"
          icon
          size="large"
          class="fab-action"
          @click="fabOpen=false; editRecipe()"
        >
          <v-icon color="white">mdi-pencil</v-icon>
        </v-btn>

                <!-- Favori -->
                <v-btn
                    v-if="!recipe?.baseRecipe"
                    color="warning"
                    icon
                    size="large"
                    class="fab-action"
                    @click="fabOpen=false; toggleFavorite()"
                >
                    <v-icon color="white">
                    {{ recipe?.favorite ? 'mdi-star' : 'mdi-star-outline' }}
                    </v-icon>
                </v-btn>

                <!-- Supprimer -->
                <v-btn
                    v-if="!recipe?.baseRecipe || authStore.userInfos?.role === 'admin'"
                    color="error"
                    icon
                    size="large"
                    class="fab-action"
                    @click="fabOpen=false; askDelete = true"
                >
                    <v-icon color="white">mdi-delete</v-icon>
                </v-btn>
                </div>
            </div>
        </v-fab-transition>


        <!-- Dialog confirmation suppression -->
        <v-dialog v-model="askDelete" max-width="420">
            <v-card>
                <v-card-title>Supprimer la recette ?</v-card-title>
                <v-card-text>
                Cette action est définitive.
                </v-card-text>
                <v-card-actions>
                <v-spacer/>
                <v-btn variant="text" @click="askDelete=false">Annuler</v-btn>
                <v-btn color="error" @click="deleteRecipe">Supprimer</v-btn>
                </v-card-actions>
            </v-card>
        </v-dialog>

        <v-snackbar v-model="snack.show" :timeout="2500">{{ snack.text }}</v-snackbar>
        <v-alert v-if="errorMessage" type="error" variant="tonal" class="mt-4">
            {{ errorMessage }}
        </v-alert>
    </v-container>
</template>

<script setup>
  import { ref, onMounted, watch, defineProps } from 'vue'
  import { useRouter } from 'vue-router'
  import { useAuthStore } from '@/store/auth_store'
  import { getUserRecipeById, deleteRecipeFromUserCollection, setRecipeAsFavorite } from '@/service/recipe_service'
  import { deleteBaseRecipe } from '@/service/recipe_manager'
  import { getBaseRecipeById } from '@/service/recipe_manager'
  import { getIngredientsByBarcodes } from '@/service/food_service'
  import TopDeck from '@/components/Utils/TopDeck.vue'

  const props = defineProps({ id: { type: String, required: true } })

  const router = useRouter()
  const authStore = useAuthStore()

  const recipe = ref(null)
  const isLoading = ref(false)
  const errorMessage = ref('')
  const snack = ref({ show: false, text: '' })

  const fabOpen = ref(false)
  const askDelete = ref(false)

  function format1(n) {
    const v = Number(n ?? 0)
    return Number.isFinite(v) ? v.toFixed(1) : '0.0'
  }

  async function loadRecipe() {
    if (!authStore.userid) return
    try {
      isLoading.value = true

      // Try to load as a user recipe first
      let r = await getUserRecipeById(authStore.userid, props.id)

      // If not found as user recipe or it's marked as baseRecipe, try loading from base catalog
      if (!r || r.baseRecipe === true) {
        const base = await getBaseRecipeById(props.id)
        if (base) {
          r = base
        } else if (!r) {
          errorMessage.value = 'Recette introuvable.'
          return
        }
      }

      // Récupère tous les barcodes de la recette
      const barcodes = r.ingredients?.map(i => i.id) || []
      const fullInfos = await getIngredientsByBarcodes(authStore.userid, barcodes)

      // Hydrate les ingrédients avec les infos
      const hydratedIngredients = (r.ingredients || []).map(line => {
        const found = fullInfos.find(f => f.id === line.id)
        return {
          ...line,
          productName: found?.productName || line.id,
          productBrand: found?.productBrand || '',
          nutritionPer100g: found?.nutritionPer100g || {}
        }
      })

      recipe.value = { id: props.id, ...r, ingredients: hydratedIngredients }
    } catch (e) {
      console.error(e)
      errorMessage.value = "Erreur lors du chargement de la recette."
    } finally {
      isLoading.value = false
    }
  }

  async function deleteRecipe() {
    if (!authStore.userid || !recipe.value?.id) return
    try {
      if (recipe.value?.baseRecipe) {
        // delete from base recipes
        await deleteBaseRecipe(recipe.value.id)
      } else {
        await deleteRecipeFromUserCollection(authStore.userid, recipe.value.id)
      }
      askDelete.value = false
      snack.value = { show: true, text: 'Recette supprimée 🗑️' }
      setTimeout(() => router.back(), 350)
    } catch (e) {
      console.error(e)
      errorMessage.value = "Erreur lors de la suppression."
    }
  }

  async function toggleFavorite() {
    if (!authStore.userid || !recipe.value?.id) return
    try {
      const next = !recipe.value.favorite
      await setRecipeAsFavorite(authStore.userid, recipe.value.id, next)
      recipe.value.favorite = next
      snack.value = { show: true, text: next ? 'Ajoutée aux favoris ⭐' : 'Retirée des favoris' }
    } catch (e) {
      console.error(e)
      errorMessage.value = "Erreur lors de la mise à jour du favori."
    } finally {
      fabOpen.value = false
    }
  }

  function editRecipe() {
    // If this is a base recipe, admins edit via the base recipes editor
    if (recipe.value?.baseRecipe) {
      if (authStore.userInfos?.role === 'admin') {
        router.push({ path: '/base_recipes', query: { id: recipe.value.id } })
        return
      }
      // Non-admins shouldn't reach here because the button is hidden,
      // but as a fallback redirect to the base recipes listing.
      router.push({ path: '/' })
      return
    }

    // Regular user recipe: open the user recipe editor
    router.push({ path: '/add_recipe', query: { id: recipe.value.id } })
  }

  onMounted(() => {
    // recharge si l’utilisateur change (sécurité) + au 1er montage
    watch(() => authStore.userid, () => loadRecipe(), { immediate: true })
  })


</script>

<style scoped>
  .fab-wrapper {
    position: fixed;
    right: 16px;
    bottom: 16px;
    display: flex;
    flex-direction: column-reverse; /* bouton principal en bas */
    align-items: flex-end;
    gap: 12px;
  }

  .fab-actions-vertical {
    display: flex;
    flex-direction: column;
    gap: 12px;
    margin-bottom: 8px;
  }

  .fab-action {
    border-radius: 9999px;
  }

  .fab-menu {
    border-radius: 16px;
  }

  .fab-actions {
    display: flex;
    gap: 10px;
  }

  .fab {
    border-radius: 9999px;
  }
</style>
