<template>
  <v-container class="py-6">
    <h2 class="text-h5 mb-6">Modifier mon profil</h2>

    <v-form ref="form" v-model="isValid" lazy-validation>
      <v-row>
        <v-col cols="12" v-for="q in questions" :key="q.key">
          <v-card class="mb-4" outlined>
            <v-card-title class="text-subtitle-1">
              {{ $t(q.key) }}
            </v-card-title>
            <v-card-text>
              <!-- Type number -->
              <v-text-field
                v-if="q.type === 'number'"
                v-model="formData[q.key]"
                type="number"
                variant="outlined"
                density="comfortable"
              />

              <!-- Type radio -->
              <v-radio-group
                v-else-if="q.type === 'radio'"
                v-model="formData[q.key]"
              >
                <v-radio
                  v-for="opt in q.options"
                  :key="opt.option"
                  :label="$t(opt.option)"
                  :value="opt.option"
                />
              </v-radio-group>

              <!-- Type checkbox -->
              <div v-else-if="q.type === 'checkbox'">
                <v-checkbox
                  v-for="opt in q.options"
                  :key="opt.option"
                  v-model="formData[q.key]"
                  :label="$t(opt.option)"
                  :value="opt.option"
                  hide-details
                  density="comfortable"
                />
              </div>
            </v-card-text>
          </v-card>
        </v-col>
      </v-row>

      <v-btn
        color="accent"
        class="mt-4"
        :disabled="!isValid"
        @click="saveProfile"
      >
        Sauvegarder
      </v-btn>
      <v-btn
        class="mt-4 ml-2"
        variant="outlined"
        @click="resetForm"
      >
        Annuler
      </v-btn>
    </v-form>
  </v-container>

 <v-snackbar
    v-model="snackbar"
    :color="snackbarColor"
    top
    right
    timeout="3500"
  >
    {{ errorMessage || snackbarMessage }}
  </v-snackbar>
</template>

<script setup>
import { reactive, watch, ref } from "vue"
import { useRouter } from 'vue-router';
import { useAuthStore } from "@/store/auth_store"
import questionsData from "@/data/register_questions.json"
import { updateUserInfos } from "@/service/user_service"

const auth = useAuthStore()
const router = useRouter();
const questions = questionsData

const snackbar = ref(false);
const errorMessage = ref("");
const snackbarMessage = ref("");
const snackbarColor = ref("success");

const showSnack = (msg, color = "success") => {
      snackbarMessage.value = msg;
      snackbarColor.value = color;
      snackbar.value = true;
    };

// 1) État réactif, pas ref({})
const formData = reactive(
  questions.reduce((acc, q) => {
    acc[q.key] = q.type === "checkbox" ? [] : ""
    return acc
  }, {})
)
const isValid = ref(false)

// 2) Surveille user et initialise les champs
watch(
  () => auth.userInfos,
  (u) => {
    if (!u) return
    questions.forEach((q) => {
      if (u[q.key] !== undefined) {
        // copie profonde pour arrays
        formData[q.key] = Array.isArray(u[q.key]) ? [...u[q.key]] : u[q.key]
      } else if (q.type === "checkbox") {
        formData[q.key] = []
      } else {
        formData[q.key] = ""
      }
    })
  },
  { immediate: true, deep: true }
)

const saveProfile = async () => {
  auth.userInfos = { ...auth.userInfos, ...formData }
  if (auth.userid) {
    try {
        await updateUserInfos(auth.userid, formData);
        showSnack("Profil mis à jour avec succès", "success");
        await new Promise(resolve => setTimeout(resolve, 500));
        router.push('/profile');
    } catch (e) {
        // Option: afficher une notification d'erreur
        console.error('Erreur lors de la mise à jour du profil utilisateur', e)
        showSnack("Erreur lors de la mise à jour du profil utilisateur", "error");
    }
  }
}

const resetForm = () => {
  if (!auth.userInfos) return
  questions.forEach((q) => {
    formData[q.key] = Array.isArray(auth.userInfos[q.key])
      ? [...auth.userInfos[q.key]]
      : auth.userInfos[q.key] ?? (q.type === "checkbox" ? [] : "")
  })
}
</script>
