<template>
  <v-card
    class="recipe-card bg-tertiary"
    max-width="380"
    elevation="0"
    outlined
  >
    <!-- IMAGE DE COUVERTURE -->
    <v-img
      height="180px"
      :src="previewSrc"
      cover
      @error="onPreviewError"
    >
      <template #placeholder>
        <v-row
          class="fill-height ma-0"
          align="center"
          justify="center"
        >
          <v-progress-circular indeterminate color="white"></v-progress-circular>
        </v-row>
      </template>
    </v-img>

    <!-- TITRE ET CATÉGORIE -->
    <v-card-title class="d-flex justify-space-between align-center">
      <span class="line-clamp-1 font-weight-medium">
        {{ item.title || "Sans titre" }}
      </span>

      <div class="d-flex align-center">
        <v-chip size="small" variant="tonal" color="accent">
          {{ $t(item.category) }}
        </v-chip>
      </div>
    </v-card-title>

    <!-- SOUS-TITRE (NOTES) -->
    <v-card-subtitle v-if="item.notes" class="text-caption text-truncate">
      {{ item.notes }}
    </v-card-subtitle>

    <!-- ACTIONS PRINCIPALES -->
    <v-card-actions>
      <v-btn color="text" variant="text" @click="viewRecipe">
        Voir
      </v-btn>

      <v-spacer></v-spacer>

      <v-btn :disabled="disabled" color="accent" variant="tonal" @click="addToCatalog">
        Ajouter
      </v-btn>

      <v-btn
        :icon="show ? 'mdi-chevron-up' : 'mdi-chevron-down'"
        variant="text"
        @click="show = !show"
      ></v-btn>
    </v-card-actions>

    <!-- CONTENU DÉPLIABLE -->
    <v-expand-transition>
      <div v-show="show">
        <v-divider></v-divider>

        <v-card-text class="text-body-2 mt-2">
          <div>
            <strong>Totaux :</strong>
            {{ item.totals?.grams ?? 0 }} g —
            {{ item.totals?.kcal ?? 0 }} kcal
            <br />
            P {{ formatValue(item.totals?.protein) }} g •
            G {{ formatValue(item.totals?.carbs) }} g •
            L {{ formatValue(item.totals?.fat) }} g
          </div>

          <div
            v-if="item.servings && item.servings > 0"
            class="text-caption mt-1"
          >
            <strong>Par portion ({{ item.servings }}) :</strong>
            {{ Math.round((item.totals?.kcal ?? 0) / item.servings) }} kcal
          </div>
        </v-card-text>
      </div>
    </v-expand-transition>
  </v-card>
</template>

<script setup>
import { ref, computed, watch } from "vue";
import { defineProps, defineEmits } from "vue";

const props = defineProps({
  item: {
    type: Object,
    required: true,
  },
  disabled: {
    type: Boolean,
    default: false,
  }
});

const emit = defineEmits(["add", "view"]);
const show = ref(false);

// Preview fallback logic: prefer item.url, then item.image, then item.imageUrl.
const validPreview = ref(true);
const placeholderImage = 'https://www.mimisrecipes.com/wp-content/uploads/2018/12/recipe-placeholder-featured.jpg'

const sourceKey = computed(() => {
  return props.item?.url || props.item?.image || props.item?.imageUrl || '';
});

const previewSrc = computed(() => {
  return validPreview.value && sourceKey.value ? sourceKey.value : placeholderImage;
});

function onPreviewError() {
  validPreview.value = false;
}

// reset validity when the source changes
watch(sourceKey, (v) => {
  validPreview.value = !!v;
});

function addToCatalog() {
  emit('add', props.item);
}

function viewRecipe() {
  emit('view', props.item.id);
}

function formatValue(value) {
  return value?.toFixed ? value.toFixed(1) : value ?? 0;
}
</script>

<style scoped>
.recipe-card {
  transition: box-shadow 0.3s ease;
}
.recipe-card:hover {
  box-shadow: 0 2px 12px rgba(0, 0, 0, 0.15);
}
.line-clamp-1 {
  display: -webkit-box;
  -webkit-line-clamp: 1;
  line-clamp: 1;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
</style>
