<template>
  <loading-element v-if="authStore.isLoading" />
  <div class="main bg-primary" v-else>
    <div class="rowSpaceBetween fullWidth mb-5">
      <TopDeck
        v-if="authStore.userInfos"
        firstElement="Mes"
        secondElement="ingrédients"
        :coloredSecond="true"
      />
      <div class="rowCustom">
        <ThemeToggle />
        <AccountToggle />
      </div>
    </div>
    <v-btn
      color="accent"
      rounded="lg"
      @click="router.push('/base_ingredients')"
      class="white-text-button mb-1"
    >
      <v-icon class="mr-1">mdi-plus</v-icon>
      <span>Ajouter ingrédients de base</span>
    </v-btn>

    <v-row class="mt-6" no-gutters>
      <!-- Liste d’ingrédients -->
      <v-col cols="12" md="9" class="pr-2">
        <div
          class="d-flex flex-column align-start justify-center pa-4 addIngredientBanner"
        >
          <h2 class="font-weight-medium mb-1">Gérez vos ingrédients</h2>
          <p class="mb-2">
            Ajoutez, modifiez et supprimez vos ingrédients pour une expérience
            personnalisée.
          </p>
          <v-btn
            color="white"
            prepend-icon="mdi-plus"
            elevation="0"
            rounded="lg"
            size="small"
            @click="router.push('/add_ingredient')"
          >
            Ajouter ingrédient
          </v-btn>
        </div>

        <v-slide-group v-model="selectedCategory" show-arrows class="mb-4">
          <v-slide-group-item
            v-for="(cat, i) in categories"
            :key="i"
            :value="cat"
          >
            <v-chip
              :color="selectedCategory === cat ? 'accent' : 'grey lighten-3'"
              :text-color="selectedCategory === cat ? 'white' : 'black'"
              class="mx-1"
              @click="
                selectedCategory = cat;
                selectedIngredient = null;
              "
            >
              {{ cat }}
            </v-chip>
          </v-slide-group-item>
        </v-slide-group>

        <div class="pa-4 bg-secondary rounded-lg">
          <h3 class="text">Votre liste</h3>

          <div v-if="isLoadingIngredients" class="d-flex justify-center my-10">
            <v-progress-circular indeterminate color="primary" />
          </div>

          <div v-else>
            <!-- Recherche + bouton -->
            <div class="d-flex align-center my-4">
              <v-text-field
                v-model="searchQuery"
                placeholder="Rechercher"
                hide-details
                density="compact"
                variant="tonal" 
                prepend-inner-icon="mdi-magnify"
                class="rounded-lg bg-tertiary"
                rounded="lg"
              />
            </div>

            <!-- Tableau -->
            <v-table density="compact" class="bg-tertiary rounded-lg">
              <thead>
                <tr>
                  <th>Ingrédient</th>
                  <!-- icône + image -->
                  <th>Nom</th>
                  <th>Catégorie</th>
                  <th>Marque</th>
                  <th>Portion (g)</th>
                </tr>
              </thead>
              <tbody>
                <tr
                  v-for="item in filteredIngredients"
                  :key="item.id"
                  @click="select(item)"
                  class="ingredients"
                >
                  <td class="d-flex align-center">
                    <v-icon
                      :color="isItemFavorite(item) ? 'orange' : 'grey lighten-1'"
                      class="mr-2"
                      size="18"
                      @click.stop="toggleFavorite(item)"
                    >
                      mdi-star
                    </v-icon>
                    <v-img
                      v-if="item.productImage"
                      :src="item.productImage"
                      width="32"
                      height="32"
                      fit
                    />
                    <v-icon v-else color="grey lighten-1" size="32"
                      >mdi-food</v-icon
                    >
                  </td>
                  <td>{{ item.productName }}</td>
                  <td>{{ item.category }}</td>
                  <td>{{ item.productBrand ?? "Inconnu" }}</td>
                  <td>{{ item.servingQuantity }} g</td>
                </tr>
              </tbody>
            </v-table>
          </div>
        </div>
      </v-col>
      
  <!-- Edit modal component -->
  <EditIngredientModal v-model="editModalOpen" :ingredient="selectedIngredient" @saved="onIngredientSaved" />

      <!-- Fiche ingrédient -->
      <v-col cols="12" md="3" class="bg-secondary pa-4 rounded-lg">
        <div v-if="selectedIngredient">
          <div class="d-flex align-start justify-space-between mb-4">
            <!-- Nom du produit -->
            <h1 class="font-weight-bold text-h5 mb-0">
              {{ selectedIngredient.productName }}
            </h1>

            <v-img
              :src="selectedIngredient.productImage"
              width="100"
              max-height="100"
              class="ml-4 rounded"
              contain
              v-if="selectedIngredient.productImage"
            />
            <v-icon v-else color="grey lighten-1" size="100" class="ml-4"
              >mdi-food-apple-outline</v-icon
            >
          </div>

          <div v-if="selectedIngredient.nutriments_map">
            <h4 class="mt-4">Nutriments</h4>
            <ul class="nutriment-list">
              <p
                v-for="(item, index) in selectedIngredient.nutriments_map"
                :key="index"
                class="nutriment-line"
              >
                <span>{{ $t(item.key) }}</span>
                <span>{{ item.value }}</span>
              </p>
            </ul>
          </div>

          <div
            v-if="
              selectedIngredient.allergens &&
              selectedIngredient.allergens.length
            "
          >
            <p class="mb-2 font-weight-medium">Allergènes :</p>
            <div class="allergen-list">
              <v-chip
                v-for="(allergen, index) in selectedIngredient.allergens"
                :key="index"
                color="blue lighten-2"
                text-color="white"
                class="ma-1"
                label
                small
              >
                {{ $t(allergen) }}
              </v-chip>
            </div>
          </div>
          <div v-else>
            <p class="text-grey">Aucun allergène</p>
          </div>

          <p class="text-red mt-2" v-if="selectedIngredient.novaGroup?.string">
            <v-chip :color="selectedIngredient.novaGroup.color">
              {{ $t(selectedIngredient.novaGroup.string) }}
            </v-chip>
          </p>
          <v-btn block class="my-2" rounded="lg" elevation="0" color="accent"
            @click="editModalOpen = true"
            >Modifier l'ingrédient</v-btn
          >
          <v-btn block class="my-2" rounded="lg" elevation="0"
            >Exclure des recettes</v-btn
          >
          <v-btn
            v-if="!selectedIngredient.isEditingDisabled"
            block
            color="black"
            class="my-2"
            rounded="lg"
            elevation="0"
            @click="deleteSelectedIngredient"
          >
            Supprimer
          </v-btn>

          <v-btn
            block
            :color="isItemFavorite(selectedIngredient) ? 'orange' : 'purple'"
            rounded="lg"
            variant="tonal"
            @click="toggleFavorite(selectedIngredient)"
          >
            {{
              isItemFavorite(selectedIngredient)
                ? "Retirer des favoris"
                : "Mettre en favoris"
            }}
          </v-btn>

        </div>
      </v-col>
    </v-row>

    <v-snackbar v-model="snackbar.show" :color="snackbar.color" timeout="3000" top right>
      {{ snackbar.text }}
    </v-snackbar>
  </div>
</template>

<script>
import { ref, computed, onMounted, watch } from "vue";
import { useRouter } from "vue-router";
import LoadingElement from "@/components/Animations/LoadingElement.vue";
import TopDeck from "@/components/Utils/TopDeck.vue";
import { useAuthStore } from "@/store/auth_store";
import {
  getUserIngredients,
  deleteIngredientFromUserCollection,
  setIngredientAsFavorite,
  getBaseIngredients,
  setBaseIngredientAsFavorite,
  updateProduct,
} from "@/service/food_service";
import EditIngredientModal from './EditIngredientModal.vue'
import ThemeToggle from "@/components/Utils/ThemeToggle.vue";
import AccountToggle from "@/components/Utils/AccountToggle.vue";

export default {
  name: "MyIngredients",
  components: { LoadingElement, TopDeck, ThemeToggle, AccountToggle, EditIngredientModal },
  setup() {
    const authStore = useAuthStore();
  const errorMessage = ref("");
  // unified snackbar for success / error feedback
  const snackbar = ref({ show: false, text: "", color: "success" });
    const router = useRouter();

    const ingredients = ref([]);
    const isLoadingIngredients = ref(false);
    const selectedIngredient = ref(null);
    const searchQuery = ref("");

    const selectedCategory = ref("Tous");
  const editModalOpen = ref(false);

    const categories = computed(() => {
      // Extraire toutes les catégories existantes dans les ingrédients
      const uniqueCategories = new Set(
        ingredients.value
          .map((item) => (item.category ?? "").trim()) // éviter null/undefined
          .filter((cat) => cat.length > 0) // ignorer vides
      );

      // Retourner "Tous" + les catégories triées
      return ["Tous", ...Array.from(uniqueCategories).sort()];
    });

    const filteredIngredients = computed(() => {
      const q = searchQuery.value.trim().toLowerCase();

      return ingredients.value.filter((item) => {
        const matchesSearch = ["productName", "productBrand", "category"].some(
          (key) => {
            return (item[key] ?? "").toLowerCase().includes(q);
          }
        );

        const matchesCategory =
          selectedCategory.value === "Tous" ||
          (item.category ?? "").toLowerCase() ===
            selectedCategory.value.toLowerCase();

        //Avec sous catégories
        // const matchesCategory =
        //   selectedCategory.value === "Tous" ||
        //   (item.category ?? "").toLowerCase().includes(selectedCategory.value.toLowerCase());

        return matchesSearch && matchesCategory;
      });
    });

    function select(item) {
      selectedIngredient.value = item;
    }

    function isItemFavorite(item) {
      if(item.isBaseIngredient) {
        return authStore.userInfos?.favoriteBaseIngredients?.includes(item.id);
      } else {
        return item.favorite;
      }
    }

    async function deleteSelectedIngredient() {
      if (!selectedIngredient.value || !authStore.userid) return;

      try {
        await deleteIngredientFromUserCollection(
          authStore.userid,
          selectedIngredient.value.id
        );

        ingredients.value = ingredients.value.filter(
          (item) => item.id !== selectedIngredient.value.id
        );

        selectedIngredient.value = null;
      } catch (err) {
        console.error("❌ Erreur suppression :", err);
        errorMessage.value = "Erreur lors de la suppression de l'ingrédient.";
        snackbar.value = { show: true, text: errorMessage.value, color: "error" };
      }
    }

  async function toggleFavorite(selectedIngredient) {

      if (!selectedIngredient || !authStore.userid) return;

      try {
        const id = selectedIngredient.id;
        const isBaseIngredient = selectedIngredient.isBaseIngredient;
        const current = ingredients.value.find((i) => i.id === id);
        if (!current) return;

        const newValue = !current.favorite;

        if(isBaseIngredient) {
          //Modify user baseIngredient favorite list
          await setBaseIngredientAsFavorite(authStore.userid, id, newValue);
        } else {
          await setIngredientAsFavorite(authStore.userid, id, newValue);
        } 
        
        // met à jour la valeur dans la liste ET la fiche
        current.favorite = newValue;
        selectedIngredient.favorite = newValue;

        // Si c'est un base ingredient, mettre à jour aussi le store utilisateur
        if (isBaseIngredient) {
          // assure que le tableau existe
          if (!Array.isArray(authStore.userInfos?.favoriteBaseIngredients)) {
            // créer la propriété si elle n'existe pas
            if (authStore.userInfos) {
              authStore.userInfos.favoriteBaseIngredients = [];
            }
          }

          const favs = authStore.userInfos.favoriteBaseIngredients;
          const idx = favs.indexOf(id);
          if (newValue && idx === -1) {
            favs.push(id);
          } else if (!newValue && idx !== -1) {
            favs.splice(idx, 1);
          }
        }
      } catch (err) {
        console.error("❌ Erreur favoris :", err);
        errorMessage.value = "Erreur lors de la mise à jour du favori.";
        snackbar.value = { show: true, text: errorMessage.value, color: "error" };
      }
    }

    async function onIngredientSaved(updated) {
      if (!updated || !authStore.userid) return;

      try {
        const id = updated.id;
        // prepare payload for user document (strip meta like source)
        const payload = { ...updated };
        delete payload.source;

        // persist to user's Ingredients doc (will merge)
        await updateProduct(authStore.userid, { [id]: payload });

        // update local list and selectedIngredient
        const idx = ingredients.value.findIndex((i) => i.id === id);
        if (idx !== -1) {
          ingredients.value[idx] = { ...ingredients.value[idx], ...payload };
        }
        selectedIngredient.value = { ...selectedIngredient.value, ...payload };
        
        // feedback
        snackbar.value = { show: true, text: "Ingrédient modifié avec succès.", color: "success" };
      } catch (err) {
        console.error('Erreur sauvegarde ingrédient :', err);
        errorMessage.value = 'Erreur lors de la sauvegarde de l\'ingrédient.';
        snackbar.value = { show: true, text: errorMessage.value, color: "error" };
      }
    }

    onMounted(() => {
      watch(
        () => authStore.userInfos,
        async () => {
          console.log("Authuserid " + authStore.userid);
          if (authStore?.userid) {
            try {
              isLoadingIngredients.value = true;
              // 1) Ingrédients user
              const userData = await getUserIngredients(authStore.userid);

              // 2) Ingrédients de base
              const baseData = await getBaseIngredients();

              // 3) Fusion
              ingredients.value = [
                ...Object.entries(userData).map(([id, value]) => ({
                  id,
                  ...value,
                  source: "user",
                })),
                  ...Object.entries(baseData).map(([id, value]) => ({
                  id,
                  ...value,
                  source: "base",
                  isBaseIngredient: true,
                  // mark favorite based on userInfos favorites array for immediate UI consistency
                  favorite: authStore.userInfos?.favoriteBaseIngredients?.includes(id) || false,
                })),
              ];
            } catch (error) {
              console.error("Erreur récupération ingrédients:", error);
              errorMessage.value = "Erreur lors du chargement des ingrédients.";
            } finally {
              isLoadingIngredients.value = false;
            }
          }
        },
        { immediate: true }
      );
    });

    return {
      selectedCategory,
      categories,
      authStore,
      errorMessage,
      snackbar,
      router,
      ingredients,
      selectedIngredient,
      select,
      searchQuery,
      filteredIngredients,
      isLoadingIngredients,
      deleteSelectedIngredient,
      toggleFavorite,
      isItemFavorite,
      editModalOpen,
      onIngredientSaved,
    };
  },
};
</script>

