<template>
  <v-card
    class="pa-4 rounded-xl"
    elevation="4"
    color="secondary"
    :disabled="item.status === 'not_found'"
  >
    <template v-if="item.status === 'found'">
      <v-row>
        <v-col cols="12" md="12">
          <v-col cols="12" md="4" class="ingredientImageContainer">
            <v-img
              :src="item.productImage"
              width="100%"
              class="rounded-lg"
              contain
            />
          </v-col>

          <div class="mt-1">
            <v-chip
              v-if="item.novaGroup?.string"
              :color="item.novaGroup.color"
              class="my-2"
              label
              small
              outlined
            >
              {{ $t(item.novaGroup.string) }}
            </v-chip>
          </div>
          
          <v-text-field
            v-model="localItem.productImage"
            label="URL de l'image"
            variant="underlined"
            density="comfortable"
          />
          <v-text-field
            v-model="localItem.productName"
            label="Nom du produit"
            variant="underlined"
            density="comfortable"
            :error="!localItem.productName"
          />
          <v-text-field
            v-model="localItem.productBrand"
            label="Marque"
            variant="underlined"
            density="comfortable"
            :error="!localItem.productBrand"
          />

          <div>
            <v-text-field
              v-model="localItem.servingQuantity"
              label="Portion (g)"
              type="number"
              variant="underlined"
              density="comfortable"
              :error="!localItem.servingQuantity"
            />
            <v-text-field
              v-model="localItem.servingSize"
              label="Taille de portion"
              variant="underlined"
              density="comfortable"
              :error="!localItem.servingSize"
            />
          </div>

          <div class="mt-3">
            <h3 class="text-subtitle-1 font-weight-medium">Allergènes</h3>
            <div class="mt-1">
              <v-chip
                v-for="(a, i) in item.allergens"
                :key="'al-' + i"
                color="orange"
                class="ma-1"
                label
                small
              >
                {{ $t(a) }}
              </v-chip>
            </div>
          </div>
        </v-col>
      </v-row>
    </template>

    <template v-else>
      <div class="d-flex align-center">
        <v-icon color="warning" class="mr-2">mdi-alert</v-icon>
        <div>
          <div class="text-subtitle-1">Entrée non valide</div>
          <div class="text-body-2 opacity-70">
            Aucune donnée exploitable pour {{ item.barcode || "—" }}
          </div>
        </div>
      </div>
    </template>

    <v-divider class="my-4" />

    <div class="d-flex justify-space-between">
      <v-chip size="small" variant="tonal" class="mr-2" color="grey">
        {{ item.barcode }}
      </v-chip>

      <div class="d-flex align-center">
        <v-btn
          size="small"
          variant="text"
          color="error"
          @click="$emit('remove')"
        >
          <v-icon size="18" class="mr-1">mdi-delete</v-icon>
          Supprimer
        </v-btn>
      </div>
    </div>
  </v-card>
</template>

<script>
export default {
  name: "ExtensionResultCard",
  props: {
    item: {
      type: Object,
      required: true
    }
  },
  emits: ['remove', 'update:item'],
  data() {
    return {
      localItem: { ...this.item }
    };
  },
  watch: {
    item: {
      handler(newVal) {
        this.localItem = { ...newVal };
      },
      deep: true
    },
    localItem: {
      handler(newVal) {
        this.$emit('update:item', newVal);
      },
      deep: true
    }
  }
};
</script>

<style scoped>
.ingredientImageContainer {
  display: flex;
  justify-content: center;
  align-items: center;
}
.opacity-70 {
  opacity: 0.7;
}
</style>