<template>
  <div>
    <v-btn
      v-if="displayLogout"
      @click="handleSignout"
      color="error"
      rounded="xl"
      class="white-text-button"
    >
      <v-icon icon="mdi-power"></v-icon>
    </v-btn>
    <v-btn
      v-else
      color="accent"
      rounded="xl"
      class="white-text-button"
      :to="profileRoute"
    >
      <v-icon icon="mdi-account"></v-icon>
    </v-btn>
  </div>
</template>

<style scoped>
.v-btn {
    border-radius: 50% !important;
    min-width: 2.25rem !important;
    width: 2.25rem !important;
    height: 2.25rem !important;
}
</style>

<script>
import { getAuth, signOut } from "firebase/auth";
import { useRouter } from "vue-router";
import { useAuthStore } from "@/store/auth_store";

export default {
  name: "AccountToggle",
  props: {
    displayLogout: {
      type: Boolean,
      default: false,
    },
  },
  setup() {
    const router = useRouter();
    const auth = getAuth();
    const authStore = useAuthStore();
    const profileRoute = "/profile";

    const handleSignout = () => {
      signOut(auth)
        .then(() => {
          router.push("/login");
        })
        .catch((error) => {
          console.error(error);
        });
    };

    return {
      handleSignout,
      profileRoute,
      authStore,
    };
  },
};
</script>

